/* 학습 해설
 * 커널 libfdt 공개 bridge·환경 선행 include
 * 동일 DTB 알고리즘을 커널의 타입·byteorder 환경과 연결하는 include·번역 단위·공개 API·링크 구성을 원본에서 읽습니다.
 * 공개 bridge는 커널 libfdt 환경을 먼저 포함해 kernel endian 타입과 변환을 선택합니다. 이후 vendored public header를 넣으므로 공개 prototype/inline과 실제 구현이 같은 환경 타입을 사용합니다. include 검색 경로로 <linux/...>를 찾는 과정과 상대 경로 source 재사용을 구별합니다.
 * 프로그램이 linux/libfdt.h를 include했을 때 환경→public API 순서를 그립니다. 실제 fixture도 이 공개 bridge로 컴파일해 empty tree/조회/편집/address/pack을 호출하며 커널 boot를 실행한 것은 아닙니다.
 */
#include <linux/libfdt_env.h>
#include "../../scripts/dtc/libfdt/libfdt.h"

#endif /* _INCLUDE_LIBFDT_H_ */

