/* 학습 해설
 * 커널 libfdt public include guard·환경과 API의 분리
 * 동일 DTB 알고리즘을 커널의 타입·byteorder 환경과 연결하는 include·번역 단위·공개 API·링크 구성을 원본에서 읽습니다.
 * _INCLUDE_LIBFDT_H_ guard는 공개 bridge를 중복 포함하지 않도록 합니다. 환경 guard LIBFDT_ENV_H와 공개 header guard는 서로 다른 범위를 보호합니다. 여러 wrapper object를 링크하는 것은 서로 다른 번역 단위를 연결하는 작업이며 guard가 object의 중복 symbol 충돌까지 제거하는 장치는 아닙니다.
 * 공개 header를 두 번 포함하는 경우와 같은 C 구현을 두 object로 중복 링크하는 경우를 비교합니다. 전처리 중복과 linker 정의 중복의 처리 단계가 다른 이유를 적습니다.
 */
#define _INCLUDE_LIBFDT_H_

#include <linux/libfdt_env.h>
#include "../../scripts/dtc/libfdt/libfdt.h"

#endif /* _INCLUDE_LIBFDT_H_ */

