/* 학습 해설
 * OF 부팅 메모리 목록 제한·reg entry 크기
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * root address/size cell 수의 합×4가 한 entry 크기입니다. /memory offset이0보다 크고 reg 길이가 limit×entry보다 크면 같은 property를 짧게 교체합니다. 이 함수는 setter 반환을 확인하지 않으며 limit 정수의 모든 범위·곱셈 overflow를 따로 검사하지 않습니다.
 * address2·size1·limit2면24byte를 계산합니다. 정상 property와 cell 수를 먼저 확인하고 전체 메모리 관리의 물리적 제거가 아니라 DTB reg 자료를 제한하는 단계임을 표시합니다.
 */
void __init of_fdt_limit_memory(int limit)
{
	int memory;
	int len;
	const void *val;
	int cell_size = sizeof(uint32_t)*(dt_root_addr_cells + dt_root_size_cells);

	memory = fdt_path_offset(initial_boot_params, "/memory");
	if (memory > 0) {
		val = fdt_getprop(initial_boot_params, memory, "reg", &len);
		if (len > limit*cell_size) {
			len = limit*cell_size;
			pr_debug("Limiting number of entries to %d\n", limit);
			fdt_setprop(initial_boot_params, memory, "reg", val,
					len);
		}
	}
}

bool of_fdt_device_is_available(const void *blob, unsigned long node)
{
	const char *status = fdt_getprop(blob, node, "status", NULL);

	if (!status)
		return true;

