 * 먼저 각 child subtree를 재귀 처리한 뒤 parent의 child 목록을 뒤집습니다. 현재 child의 next를 저장하고 sibling을 새 head로 바꾼 뒤 저장한 next로 전진합니다. node bytes나 payload를 복사하지 않고 pointer 연결만 바꾸며 실제 fixture에서 두 깊이의 순서를 확인했습니다.
 * c,b,a와 a의 y,x를 각각a,b,c와x,y로 바꾸는 검산을 읽습니다. next 저장 없이 sibling을 바꾸면 남은 목록을 잃는 이유와 재귀 깊이 전제를 설명합니다.
 */
static void reverse_nodes(struct device_node *parent)
{
	struct device_node *child, *next;

	/* In-depth first */
	child = parent->child;
	while (child) {
		reverse_nodes(child);

		child = child->sibling;
	}

	/* Reverse the nodes in the child list */
	child = parent->child;
	parent->child = NULL;
	while (child) {
		next = child->sibling;

		child->sibling = parent->child;
		parent->child = child;
		child = next;
	}
}

