/* 학습 해설
 * OF crash dump elfcorehdr·예약 중복 검사
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * CRASH_DUMP가 켜지고 elfcorehdr_size가 있을 때 기존 예약 여부를 검사합니다. 이미 예약된 region이면 경고하고 끝내며 나머지는 memblock_reserve합니다. crash capture kernel이 이전 kernel의 core 정보를 읽을 영역을 일반 allocation과 구별하는 단계입니다.
 * 예약없음/기예약/설정꺼짐/size0의 분기를 적습니다. overlap 정책과 memblock 반환값의 실제 처리 범위를 확인하며 전체 crash dump 기능 실행으로 확대하지 않습니다.
 */
static void __init fdt_reserve_elfcorehdr(void)
{
	if (!IS_ENABLED(CONFIG_CRASH_DUMP) || !elfcorehdr_size)
		return;

	if (memblock_is_region_reserved(elfcorehdr_addr, elfcorehdr_size)) {
		pr_warn("elfcorehdr is overlapped\n");
		return;
	}

	memblock_reserve(elfcorehdr_addr, elfcorehdr_size);

	pr_info("Reserving %llu KiB of memory at 0x%llx for elfcorehdr\n",
		elfcorehdr_size >> 10, elfcorehdr_addr);
}

