/* 학습 해설
 * OF 예약 메모리 순서·노드와 header memreserve
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * boot blob이 있으면 reserved-memory scan→elfcorehdr reserve→header reserve entries→reserved-memory 초기화 순서입니다. header entries는 size0을 끝으로 사용하고각base/size를memblock_reserve합니다. 이 본문은 fdt_get_mem_rsv 반환을 별도 검사하지 않아 정상 reserve 표 계약을 읽어야 합니다.
 * reserved-memory node와 header memreserve를 서로 다른 자료로 그립니다. 각각의 등록/초기화 순서와0size 종료 조건을 표시하고 malformed reserve table을 실제 fixture로 검증한 것은 아님을 적습니다.
 */
void __init early_init_fdt_scan_reserved_mem(void)
{
	int n;
	u64 base, size;

	if (!initial_boot_params)
		return;

	fdt_scan_reserved_mem();
	fdt_reserve_elfcorehdr();

	/* Process header /memreserve/ fields */
	for (n = 0; ; n++) {
		fdt_get_mem_rsv(initial_boot_params, n, &base, &size);
		if (!size)
			break;
		memblock_reserve(base, size);
	}

	fdt_init_reserved_mem();
}

