/* 학습 해설
 * OF flat 전체 scan·callback과 조기 종료
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * blob이 없으면0입니다. fdt_next_node를offset-1/depth-1에서 시작해 root와하위를 순회하고 callback에offset/name/depth/data를 전달합니다. callback의nonzero rc면반복을 끝내고그값을 반환합니다. traversal 오류 자체를 모든 경우 caller에게 전파하는 wrapper는 아닙니다.
 * 실제4node fixture의depth0,1,1,2와두번째callback에서7로끝나는검산을 읽습니다. callbackcontext data와 전역bootblob을 구별하고 iterator 종료와 callback 반환을 별도로 표시합니다.
 */
int __init of_scan_flat_dt(int (*it)(unsigned long node,
				     const char *uname, int depth,
				     void *data),
			   void *data)
{
	const void *blob = initial_boot_params;
	const char *pathp;
	int offset, rc = 0, depth = -1;

	if (!blob)
		return 0;

	for (offset = fdt_next_node(blob, -1, &depth);
	     offset >= 0 && depth >= 0 && !rc;
	     offset = fdt_next_node(blob, offset, &depth)) {

		pathp = fdt_get_name(blob, offset, NULL);
		rc = it(offset, pathp, depth, data);
	}
	return rc;
}

