/* 학습 해설
 * OF compatible 우선순위·문자열 목록의1기반 점수
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * compatible NUL목록을앞부터읽고첫match의1기반score를반환합니다.없거나불일치는0이며작은양수가더구체적인앞순위입니다. strlen으로다음문자열로가므로정상종료목록계약이필요하며임의malformed자료안전성을이본문이보장하지않습니다.
 * specific,generic목록의점수1/2와부재0을실제검산합니다. libfdt fdt_node_check_compatible의0match계약과이OFscore의nonzero match를서로혼동하지않습니다.
 */
static int of_fdt_is_compatible(const void *blob,
		      unsigned long node, const char *compat)
{
	const char *cp;
	int cplen;
	unsigned long l, score = 0;

	cp = fdt_getprop(blob, node, "compatible", &cplen);
	if (cp == NULL)
		return 0;
	while (cplen > 0) {
		score++;
		if (of_compat_cmp(cp, compat, strlen(compat)) == 0)
			return score;
		l = strlen(cp) + 1;
		cp += l;
		cplen -= l;
	}

	return 0;
}

