/* 학습 해설
 * OF machine table match·최소 양수와 동점
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * table의호환문자열마다OFscore를구하고0이아닌최소값을선택합니다. tableNULL이면0입니다. 상위of_flat_dt_match_machine은callback의각table을검사해strictlysmaller일때best를바꿔동점이면먼저선택한결과를유지하고기본값을fallback으로씁니다.
 * tablegeneric2와specific1/동점specific1에서두번째table선택후세번째동점이덮지않는실제검산을읽습니다. 이름hash검색이아니라목록과table의반복탐색비용을설명합니다.
 */
static int __init of_flat_dt_match(unsigned long node, const char *const *compat)
{
	unsigned int tmp, score = 0;

	if (!compat)
		return 0;

	while (*compat) {
		tmp = of_fdt_is_compatible(initial_boot_params, node, *compat);
		if (tmp && (score == 0 || (tmp < score)))
			score = tmp;
		compat++;
	}

	return score;
}

