/* 학습 해설
 * OF initrd 가상주소·architecture 조건
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * ARM64와64bitRISCV에서는이earlyhelper가__va를설정하지않습니다. 다른조건에서는initrd_start/end에가상변환을넣고below_start_ok를1로합니다. 일부platform에서너무이른__va대신phys_initrd정보를사용하도록분리한기술입니다.
 * ARM64/RISCV64/다른architecture분기를표로만들고물리정보설정은상위check_for_initrd에서따로수행됨을표시합니다. 이선택함수fixture가실제earlyVA변환을실행한것은아닙니다.
 */
static void __early_init_dt_declare_initrd(unsigned long start,
					   unsigned long end)
{
	/*
	 * __va() is not yet available this early on some platforms. In that
	 * case, the platform uses phys_initrd_start/phys_initrd_size instead
	 * and does the VA conversion itself.
	 */
	if (!IS_ENABLED(CONFIG_ARM64) &&
	    !(IS_ENABLED(CONFIG_RISCV) && IS_ENABLED(CONFIG_64BIT))) {
		initrd_start = (unsigned long)__va(start);
		initrd_end = (unsigned long)__va(end);
		initrd_below_start_ok = 1;
	}
}

