 * BLK_DEV_INITRD가켜지고start/end둘다있으면of_read_number로len/4cells를읽습니다. start>end는반환하고정상은phys_start=start,size=end-start입니다. 같은start/end는size0이며본문은모든property폭·len%4·지원address범위를독립검사하지않습니다.
 * start0x1000/end0x3000의size0x2000과역순거부를계산합니다. end가exclusive끝이라는길이산식과정상cell자료전제를적고임의malformedinitrd검증으로확대하지않습니다.
 */
static void __init early_init_dt_check_for_initrd(unsigned long node)
{
	u64 start, end;
	int len;
	const __be32 *prop;

	if (!IS_ENABLED(CONFIG_BLK_DEV_INITRD))
		return;

	pr_debug("Looking for initrd properties... ");

	prop = of_get_flat_dt_prop(node, "linux,initrd-start", &len);
	if (!prop)
		return;
	start = of_read_number(prop, len/4);

	prop = of_get_flat_dt_prop(node, "linux,initrd-end", &len);
	if (!prop)
		return;
	end = of_read_number(prop, len/4);
	if (start > end)
		return;

	__early_init_dt_declare_initrd(start, end);
	phys_initrd_start = start;
	phys_initrd_size = end - start;

