/* 학습 해설
 * OF usable-memory-range·최대2개와cap/add
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * chosen offset이음수면반환합니다. linux,usable-memory-range에서최대2개base/size를읽고첫range로memblock_cap_memory_range후두번째nonzero를add합니다. len modulus도cells합을사용해byte/cell단위와완전entry경계검사를같다고설명하지않습니다.
 * high/low두range와첫cap뒤추가등록순서를그립니다. MAX_USABLE_RANGES2와낮은range를마지막에두는호환성주석을읽고property부재와0size조건을구별합니다.
 */
void __init early_init_dt_check_for_usable_mem_range(void)
{
	struct memblock_region rgn[MAX_USABLE_RANGES] = {0};
	const __be32 *prop, *endp;
	int len, i;
	unsigned long node = chosen_node_offset;

	if ((long)node < 0)
		return;

	pr_debug("Looking for usable-memory-range property... ");

	prop = of_get_flat_dt_prop(node, "linux,usable-memory-range", &len);
	if (!prop || (len % (dt_root_addr_cells + dt_root_size_cells)))
		return;

	endp = prop + (len / sizeof(__be32));
	for (i = 0; i < MAX_USABLE_RANGES && prop < endp; i++) {
		rgn[i].base = dt_mem_next_cell(dt_root_addr_cells, &prop);
		rgn[i].size = dt_mem_next_cell(dt_root_size_cells, &prop);

		pr_debug("cap_mem_regions[%d]: base=%pa, size=%pa\n",
			 i, &rgn[i].base, &rgn[i].size);
	}

	memblock_cap_memory_range(rgn[0].base, rgn[0].size);

