/* 학습 해설
 * OF early stdout 경로·alias와colon options
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * chosen또는chosen@0에서stdout-path,없으면linux,stdout-path를찾습니다. 첫colon앞길이로nodepath를조회하고뒤문자열을options로둡니다. 원본문자열을split하여수정하지않고길이제한path조회에전달해alias지원libfdt와연결합니다.
 * serial0:115200n8을path/options로나눕니다. chosen부재/속성부재는ENOENT지만지정node조회실패는경고뒤0인서로다른반환정책을원문에서표시합니다.
 */
int __init early_init_dt_scan_chosen_stdout(void)
{
	int offset;
	const char *p, *q, *options = NULL;
	int l;
	const struct earlycon_id *match;
	const void *fdt = initial_boot_params;
	int ret;

	offset = fdt_path_offset(fdt, "/chosen");
	if (offset < 0)
		offset = fdt_path_offset(fdt, "/chosen@0");
	if (offset < 0)
		return -ENOENT;

	p = fdt_getprop(fdt, offset, "stdout-path", &l);
	if (!p)
		p = fdt_getprop(fdt, offset, "linux,stdout-path", &l);
	if (!p || !l)
		return -ENOENT;

	q = strchrnul(p, ':');
	if (*q != '\0')
		options = q + 1;
	l = q - p;

